#include "exotic/cognition/cognitive_budget.hpp"
#include <algorithm>
namespace exotic::cognition {
void CognitiveBudget::reset(double capacity){if(capacity>=0.0)capacity_=std::clamp(capacity,0.0,1.0);remaining_=capacity_;}
void CognitiveBudget::stop_topic(const std::string&id){auto&s=topics_[id];s.topic_id=id;s.stopped=true;}
void CognitiveBudget::resume_topic(const std::string&id){auto&s=topics_[id];s.topic_id=id;s.stopped=false;s.repeats_in_window=0;s.cooldown_until=0;}
AttentionDecision CognitiveBudget::consider(const std::string&id,std::int64_t now,double cost,double novelty){auto&s=topics_[id];s.topic_id=id;AttentionDecision d;d.remaining_budget=remaining_;if(s.stopped){d.disposition=AttentionDisposition::StopTopic;d.rationale="This topic is deliberately stopped; resumption requires an explicit choice.";return d;}if(s.cooldown_until>now){d.disposition=AttentionDisposition::Cooldown;d.novelty_multiplier=0.0;d.rationale="Topic is cooling down to avoid repetitive attention loops.";return d;}cost=std::clamp(cost,0.0,1.0);if(cost>remaining_){d.disposition=AttentionDisposition::BudgetExhausted;d.rationale="Current cognitive budget is insufficient; deferral is preferred over forced continuation.";return d;}if(s.last_considered>0&&now-s.last_considered<=300)++s.repeats_in_window;else s.repeats_in_window=0;s.last_considered=now;d.novelty_multiplier=std::clamp(novelty,0.0,1.0)/(1.0+0.5*s.repeats_in_window);remaining_=std::max(0.0,remaining_-cost);d.remaining_budget=remaining_;if(s.repeats_in_window>=3){s.cooldown_until=now+600;d.disposition=AttentionDisposition::Cooldown;d.rationale="Repeated consideration triggered a temporary cooldown; the topic remains available later.";}else{d.disposition=AttentionDisposition::Consider;d.rationale="Topic fits the current attention budget and repetition limits.";}return d;}
} // namespace exotic::cognition
